// Social sign-in (OAuth PKCE): see the module notes in the generator's
// emit/socialauth.ts. The exchange response feeds setSession automatically
// through apiFetch — no session code here on purpose.

import * as Linking from 'expo-linking';
import * as WebBrowser from 'expo-web-browser';

/** Run the OAuth PKCE browser flow; resolves the callback code + verifier. */
export async function runOAuthPkce(
  base: string,
  path: string,
  provider: string,
): Promise<OAuthFlowResult> {
  const verifier = randomVerifier();
  const redirectTo = Linking.createURL('auth-callback');
  const url = authorizeUrl(base, path, provider, redirectTo, verifier, 'plain');
  await probeAuthorize(url, provider);
  const result = await WebBrowser.openAuthSessionAsync(url, redirectTo);
  if (result.type !== 'success' || !('url' in result) || !result.url) {
    throw new Error('Sign-in was cancelled.');
  }
  const parsed = parseCode(result.url);
  if (!parsed.code) throw new Error(parsed.error ?? 'Sign-in was not completed.');
  return { code: parsed.code, verifier };
}

export interface OAuthFlowResult {
  code: string;
  verifier: string;
}

function randomVerifier(): string {
  const bytes = new Uint8Array(32);
  // Hermes and every browser expose crypto.getRandomValues, and the app entry
  // imports react-native-get-random-values so it is always there.
  //
  // There used to be a Math.random fallback here, "to keep old debug runtimes
  // alive (verifier secrecy degrades, PKCE still binds the code to this app
  // instance)". But the verifier IS the secret that binding rests on, and
  // Math.random is seeded per process under Hermes — a runtime that reaches
  // the fallback ships a PKCE flow whose verifier is guessable, silently.
  // Refusing loudly is the only honest option, and it is what
  // newIdempotencyKey does in api/client.ts for the same reason.
  const c = (globalThis as any).crypto;
  if (!c?.getRandomValues) {
    throw new Error(
      'no CSPRNG available for a PKCE verifier — install react-native-get-random-values',
    );
  }
  c.getRandomValues(bytes);
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let out = '';
  for (const b of bytes) out += alphabet[b & 63];
  return out;
}

function authorizeUrl(
  base: string,
  path: string,
  provider: string,
  redirectTo: string,
  challenge: string,
  method: string,
): string {
  const q =
    'provider=' +
    encodeURIComponent(provider) +
    '&redirect_to=' +
    encodeURIComponent(redirectTo) +
    '&code_challenge=' +
    encodeURIComponent(challenge) +
    '&code_challenge_method=' +
    method;
  return base.replace(/\/$/, '') + path + '?' + q;
}

function parseCode(url: string): { code?: string; error?: string } {
  const q = url.includes('?') ? url.slice(url.indexOf('?') + 1).split('#')[0] : '';
  const out: { code?: string; error?: string } = {};
  for (const pair of q.split('&')) {
    const i = pair.indexOf('=');
    const k = i < 0 ? pair : pair.slice(0, i);
    const v = i < 0 ? '' : decodeURIComponent(pair.slice(i + 1));
    if (k === 'code') out.code = v;
    if (k === 'error_description' && v) out.error = v;
    if (k === 'error' && v && !out.error) out.error = v;
  }
  return out;
}

/** A configured provider 302s to the IdP; an unconfigured one answers 400
 * with a message naming the provider — surface THAT, honestly. */
async function probeAuthorize(url: string, provider: string): Promise<void> {
  try {
    const res = await fetch(url);
    if (res.status === 400 || res.status === 422) {
      let msg = '';
      try {
        msg = ((await res.json()) as any)?.msg ?? '';
      } catch {
        /* not json */
      }
      const name = provider.charAt(0).toUpperCase() + provider.slice(1);
      throw new Error(
        name +
          " sign-in isn't configured for this backend yet" +
          (msg ? ' (' + msg + ')' : '') +
          '.',
      );
    }
  } catch (e) {
    if (e instanceof Error && /isn't configured/.test(e.message)) throw e;
    // network trouble on the probe is not proof of anything — let the real
    // browser flow decide
  }
}
